out=[row.copy() for row in grid]
# recompute components and mark suffix after component's rightmost column in each row where that maximum is reached
pts={(r,c) for r in range(23) for c in range(17) if grid[r][c]==3}
changes=set()
while pts:
    seed=pts.pop(); comp={seed}; stack=[seed]
    while stack:
        r,c=stack.pop()
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                q=(r+dr,c+dc)
                if q in pts:
                    pts.remove(q); comp.add(q); stack.append(q)
    mx=max(c for r,c in comp)
    for r,c in comp:
        if c==mx:
            for j in range(c+1,17):
                if out[r][j]==7:
                    out[r][j]=1; changes.add((r,j))
[(r, sorted(c for rr,c in changes if rr==r)) for r in range(23) if any(rr==r for rr,c in changes)], [len(x) for x in out]

